BEGIN;
SET LOCAL lock_timeout='5s';SET LOCAL statement_timeout='30s';
DO $readmit$
DECLARE ctl jsonb;old_assignment jsonb;new_assignment jsonb;before_controls jsonb;after_controls jsonb;
before_task jsonb;new_id bigint;review_id bigint;old_hash text;definition_hashes jsonb;current_daily_hash text;existing bigint;
BEGIN
ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
PERFORM population_top3000_202608_202609_v1.ref01_practical_guard_v1();
SELECT details INTO STRICT old_assignment FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=25098 AND event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5';
old_hash:=encode(sha256(convert_to(old_assignment::text,'UTF8')),'hex');
IF old_hash IS DISTINCT FROM 'fd5dc592274f69f2badd494f1e7c5ab9d04e25250aa9cae499a1c6792f9521cd' OR old_assignment->>'assigned_executor' IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR old_assignment->>'root_will_not_concurrently_modify' IS DISTINCT FROM 'true' OR old_assignment->>'exclusive_component' IS DISTINCT FROM 'CTX06_PRACTICAL_BREADTH_PRODUCER_V2' OR old_assignment->>'owner_id' IS DISTINCT FROM ctl->>'owner_id' OR old_assignment->>'owner_fence' IS DISTINCT FROM ctl->>'owner_fence' OR old_assignment->>'stop_generation' IS DISTINCT FROM ctl->>'stop_generation' OR old_assignment->>'scope_sha256' IS DISTINCT FROM ctl->>'scope_sha256' THEN RAISE EXCEPTION 'EXACT_PRIOR_DELEGATION_REQUIRED';END IF;
IF (old_assignment->>'not_after')::timestamptz>clock_timestamp() OR (ctl->>'not_after')::timestamptz<=clock_timestamp()+interval '35minutes' THEN RAISE EXCEPTION 'EXPIRED_ASSIGNMENT_AND_CURRENT_FINITE_WINDOW_REQUIRED';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE e.event='ENGINEERING_ASSIGNMENT_CLAIMED_V5' AND e.details->>'exclusive_component'=old_assignment->>'exclusive_component' AND NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event d WHERE d.event IN ('ENGINEERING_ASSIGNMENT_COMPLETED_V5','ENGINEERING_ASSIGNMENT_EFFECTS_RECONCILED_RELEASE_V5') AND d.details->>'claim_event_id'=e.event_id::text AND d.details->>'effects_known'='true')) THEN RAISE EXCEPTION 'EXISTING_UNRECONCILED_COMPONENT_CLAIM';END IF;
SELECT event_id INTO existing FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5' AND details->>'readmission_of_assignment_event_id'='25098' ORDER BY event_id DESC LIMIT 1;
IF existing IS NOT NULL THEN RAISE EXCEPTION 'EXISTING_EXACT_READMISSION_USE_SUCCESSOR %',existing;END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX06' AND status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE family_id='CTX06' AND status='CLAIMED') THEN RAISE EXCEPTION 'ACTIVE_CTX06_OPERATION_REQUIRED_HANDOVER';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.ref01_practical_snapshot_v1 s JOIN population_top3000_202608_202609_v1.ref01_practical_membership_v1 m USING(snapshot_sha256) WHERE s.snapshot_sha256=old_assignment#>>'{input_versions,cohort_sha256}' AND s.policy_sha256=old_assignment->>'policy_sha256' AND encode(sha256(convert_to(s.content::text,'UTF8')),'hex')=s.snapshot_sha256 AND m.acceptance_sha256=old_assignment#>>'{input_versions,membership_acceptance_sha256}' AND encode(sha256(convert_to(m.content::text,'UTF8')),'hex')=m.acceptance_sha256 AND s.content->>'selected_company_count'='3000') THEN RAISE EXCEPTION 'EXACT_ACCEPTED_PRACTICAL_COHORT_REQUIRED';END IF;
SELECT encode(sha256(convert_to(input_versions::text,'UTF8')),'hex') INTO current_daily_hash FROM population_top3000_202608_202609_v1.daily_shared_run_v1 WHERE run_id=(old_assignment#>>'{input_versions,daily_run_id}')::uuid AND normalized_series=series_count AND derived_series=series_count AND normalized_at IS NOT NULL AND derived_at IS NOT NULL;
IF current_daily_hash IS DISTINCT FROM old_assignment#>>'{input_versions,daily_input_versions_sha256}' THEN RAISE EXCEPTION 'DAILY_SOURCE_PREIMAGE_CHANGED';END IF;
SELECT jsonb_object_agg(proname,encode(sha256(convert_to(pg_get_functiondef(oid),'UTF8')),'hex')) INTO definition_hashes FROM pg_proc WHERE pronamespace='population_top3000_202608_202609_v1'::regnamespace AND proname IN ('ctx06_acquire_v1','ctx06_dependencies_v1','ctx06_prepare_v1','ctx06_context_v1','ctx06_normalize_v1','ctx06_derive_v1','ctx06_quality_hold_v1','sequencing_dependency_wake_v1','ref01_practical_guard_v1','pipeline_enqueue_v1');
IF jsonb_typeof(definition_hashes) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(definition_hashes))<>10 THEN RAISE EXCEPTION 'TEN_REQUIRED_CODE_PREIMAGES_MISSING';END IF;
SELECT jsonb_build_object('acquisition',to_jsonb(a),'pipeline',to_jsonb(p)) INTO before_controls FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
SELECT to_jsonb(t) INTO STRICT before_task FROM population_top3000_202608_202609_v1.pipeline_task t WHERE task_id='467735a6-c132-4678-b853-242383a738f9';
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_ASSIGNMENT_READMISSION_INDEPENDENT_REVIEW_V1',ctl||jsonb_build_object('approved',true,'approval_scope','EXACT_SAME_SCOPE_APPEND_ONLY_ADMISSION_RENEWAL','producer','automation:6adc2c96db348191bca7cf4eacfdac32','reviewer','/root/verify_daily_dependency','prior_assignment_event_id',25098,'prior_assignment_sha256',old_hash,'prior_not_after',old_assignment->>'not_after','new_not_after',ctl->>'not_after','fresh_code_preimages',definition_hashes,'preserve_all_operational_bounds',true,'source_calls',0,'root_acceptance_delegated',false)) RETURNING event_id INTO review_id;
new_assignment:=old_assignment||jsonb_build_object('assignment_id','ctx06-practical-breadth-producer-v2-readmitted-20261024','not_after',ctl->>'not_after','parent_assignment_event_id',25098,'readmission_of_assignment_event_id',25098,'prior_assignment_sha256',old_hash,'prior_not_after',old_assignment->>'not_after','readmission_review_event_id',review_id,'readmission_executor','automation:6adc2c96db348191bca7cf4eacfdac32','fresh_code_preimages',definition_hashes);
IF (new_assignment-ARRAY['assignment_id','not_after','parent_assignment_event_id','readmission_of_assignment_event_id','prior_assignment_sha256','prior_not_after','readmission_review_event_id','readmission_executor','fresh_code_preimages']) IS DISTINCT FROM (old_assignment-ARRAY['assignment_id','not_after','parent_assignment_event_id']) THEN RAISE EXCEPTION 'READMISSION_SCOPE_OR_BOUNDS_CHANGED';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_IMPLEMENTATION_ASSIGNMENT_V5',new_assignment) RETURNING event_id INTO new_id;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('ENGINEERING_ASSIGNMENT_ADMISSION_RENEWED_V5',ctl||jsonb_build_object('executor','automation:6adc2c96db348191bca7cf4eacfdac32','prior_assignment_event_id',25098,'prior_assignment_sha256',old_hash,'successor_assignment_event_id',new_id,'successor_assignment_sha256',encode(sha256(convert_to(new_assignment::text,'UTF8')),'hex'),'independent_review_event_id',review_id,'prior_not_after',old_assignment->>'not_after','new_not_after',ctl->>'not_after','effects_known',true,'source_calls',0,'family_accepted',false,'counters_and_original_deadline_preserved',true,'original_assignment_preserved',true));
SELECT jsonb_build_object('acquisition',to_jsonb(a),'pipeline',to_jsonb(p)) INTO after_controls FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
IF before_controls IS DISTINCT FROM after_controls OR before_task IS DISTINCT FROM (SELECT to_jsonb(t) FROM population_top3000_202608_202609_v1.pipeline_task t WHERE task_id='467735a6-c132-4678-b853-242383a738f9') OR old_hash IS DISTINCT FROM (SELECT encode(sha256(convert_to(details::text,'UTF8')),'hex') FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=25098) THEN RAISE EXCEPTION 'READMISSION_ALTERED_CONTROL_TASK_OR_HISTORY';END IF;
END $readmit$;
-- Append COMMIT only after independent rollback review.
